import random

def beats_count(die_a, die_b):
    count = 0
    for a in die_a:
        for b in die_b:
            if a > b:
                count += 1
    return count

random.seed(42)

best = None
best_min_beats = 0

for trial in range(200000):
    dice = []
    for i in range(5):
        faces = sorted(random.choices(range(12), k=6))
        dice.append(faces)

    min_beats = min(beats_count(dice[i], dice[(i+1)%5]) for i in range(5))
    if min_beats > best_min_beats:
        best_min_beats = min_beats
        best = [d[:] for d in dice]
        if min_beats > 18:
            print(f"Found solution at trial {trial}!")
            print(f"Min beats: {min_beats}")
            for i, d in enumerate(dice):
                print(f"Die {i}: {d}")
            break

if best_min_beats <= 18:
    print(f"Best min beats found: {best_min_beats}")
    for i, d in enumerate(best):
        print(f"Die {i}: {d}")
